+            platform: NotificationPlatform::Macos,
+            supported: true,
+            authorization: NotificationAuthorization::Unknown,
+            alerts_enabled: None,
+            sounds_enabled: None,
+            requested: false,
+            authoritative: false,
+            can_open_settings: true,
+        }
+    }
