+#[test]
+fn validate_resolves_indirect_paths_to_a_canonical_location() {
+    let dir = tempfile::TempDir::new().expect("tempdir");
+    let path = dir.path().join("ding.wav");
+    std::fs::write(&path, b"placeholder").expect("write file");
