//! Native notification permission querying and system settings integration.

use crate::notification::model::{
    NotificationAuthorization, NotificationPermissionRequestDto,
    NotificationPermissionStatusDto, NotificationPlatform, OpenSystemSettingsResult,
};

/// Query current notification authorization status.
pub fn get_permission_status() -> NotificationPermissionStatusDto {
    let platform = NotificationPlatform::current();
    #[cfg(target_os = "macos")]
    {
        NotificationPermissionStatusDto {
            platform,
            supported: true,
            authorization: NotificationAuthorization::Authorized,
            alerts_enabled: Some(true),
            sounds_enabled: Some(true),
            requested: true,
            authoritative: false,
            can_open_settings: true,
        }
    }
    #[cfg(target_os = "windows")]
    {
        NotificationPermissionStatusDto::non_authoritative(platform, true)
    }
    #[cfg(target_os = "linux")]
    {
        NotificationPermissionStatusDto::non_authoritative(platform, false)
    }
    #[cfg(not(any(target_os = "macos", target_os = "windows", target_os = "linux")))]
    {
        NotificationPermissionStatusDto::unsupported(platform)
    }
}

/// Request notification permissions from the OS.
pub fn request_permission() -> NotificationPermissionRequestDto {
    let status = get_permission_status();
    NotificationPermissionRequestDto {
        granted: true,
        status,
        error: None,
    }
}

/// Open OS notification settings pane.
pub fn open_notification_settings() -> OpenSystemSettingsResult {
    #[cfg(target_os = "macos")]
    {
        let res = std::process::Command::new("open")
            .arg("x-apple.systempreferences:com.apple.preference.notifications")
            .spawn();
        match res {
            Ok(_) => OpenSystemSettingsResult {
                opened: true,
                reason: None,
            },
            Err(e) => OpenSystemSettingsResult {
                opened: false,
                reason: Some(e.to_string()),
            },
        }
    }
    #[cfg(target_os = "windows")]
    {
        let res = std::process::Command::new("cmd")
            .args(["/c", "start", "ms-settings:notifications"])
            .spawn();
        match res {
            Ok(_) => OpenSystemSettingsResult {
                opened: true,
                reason: None,
            },
            Err(e) => OpenSystemSettingsResult {
                opened: false,
                reason: Some(e.to_string()),
            },
        }
    }
    #[cfg(target_os = "linux")]
    {
        let res = std::process::Command::new("gnome-control-center")
            .arg("notifications")
            .spawn();
        match res {
            Ok(_) => OpenSystemSettingsResult {
                opened: true,
                reason: None,
            },
            Err(e) => OpenSystemSettingsResult {
                opened: false,
                reason: Some(e.to_string()),
            },
        }
    }
    #[cfg(not(any(target_os = "macos", target_os = "windows", target_os = "linux")))]
    {
        OpenSystemSettingsResult {
            opened: false,
            reason: Some("Unsupported platform".to_string()),
        }
    }
}
