//! Authoritative notification permission queries.
//!
//! Tauri's desktop `permission_state()` unconditionally returns `Granted`, so
//! it cannot detect a user who disabled rorca notifications in System
//! Settings. On macOS this module queries `UNUserNotificationCenter` instead.
//! Windows and Linux report a non-authoritative `unknown` until a real
//! platform query is implemented for them.

use super::model::{
    NotificationAuthorization, NotificationPermissionRequestDto, NotificationPermissionStatusDto,
    NotificationPlatform,
};

/// Seam over the OS permission backend.
///
/// Tests substitute a fake so CI never depends on the host machine's real
/// notification authorization.
pub trait NotificationPermissionProvider: Send + Sync {
    fn status(&self) -> NotificationPermissionStatusDto;

    /// Explicit, user-initiated authorization request.
    ///
    /// Must never be called at startup or from a background event.
    fn request(&self) -> NotificationPermissionRequestDto;
}

/// Provider selected for the current build target.
pub fn platform_permission_provider() -> Box<dyn NotificationPermissionProvider> {
    #[cfg(target_os = "macos")]
    {
        Box::new(macos::MacosPermissionProvider)
    }
    #[cfg(not(target_os = "macos"))]
    {
        Box::new(DesktopFallbackPermissionProvider)
    }
}

/// Non-authoritative provider for platforms without a real permission query.
///
/// It reports `unknown` rather than `authorized` so the UI never claims
/// notifications work when they may be silently dropped.
#[derive(Debug, Default, Clone, Copy)]
pub struct DesktopFallbackPermissionProvider;

impl NotificationPermissionProvider for DesktopFallbackPermissionProvider {
    fn status(&self) -> NotificationPermissionStatusDto {
        let platform = NotificationPlatform::current();
        let can_open_settings = matches!(platform, NotificationPlatform::Windows);
        NotificationPermissionStatusDto::non_authoritative(platform, can_open_settings)
    }

    fn request(&self) -> NotificationPermissionRequestDto {
        // No system prompt exists on these targets; report current state
        // rather than fabricating a grant.
        NotificationPermissionRequestDto {
            granted: false,
            status: self.status(),
            error: None,
        }
    }
}

#[cfg(target_os = "macos")]
pub mod macos {
    use super::*;
    use block2::RcBlock;
    use objc2_foundation::{NSBundle, NSError};
    use objc2_user_notifications::{
        UNAuthorizationOptions, UNAuthorizationStatus, UNNotificationSetting,
        UNNotificationSettings, UNUserNotificationCenter,
    };
    use std::ptr::NonNull;
    use std::sync::mpsc;
    use std::time::Duration;

    /// UserNotifications callbacks must not block a caller forever.
    const CALLBACK_TIMEOUT: Duration = Duration::from_secs(5);

    /// Map Apple's authorization status, preserving unknown future values.
    pub fn map_authorization_status(status: UNAuthorizationStatus) -> NotificationAuthorization {
        match status {
            UNAuthorizationStatus::NotDetermined => NotificationAuthorization::NotDetermined,
            UNAuthorizationStatus::Denied => NotificationAuthorization::Denied,
            UNAuthorizationStatus::Authorized => NotificationAuthorization::Authorized,
            UNAuthorizationStatus::Provisional => NotificationAuthorization::Provisional,
            UNAuthorizationStatus::Ephemeral => NotificationAuthorization::Provisional,
            // A future macOS value must never be optimistically authorized.
            _ => NotificationAuthorization::Unknown,
        }
    }

    /// Map an alert/sound setting to a nullable boolean.
    ///
    /// `NotSupported` becomes `None` rather than `false`: an unsupported sound
    /// setting must never be mistaken for denied authorization.
    pub fn map_notification_setting(setting: UNNotificationSetting) -> Option<bool> {
        match setting {
            UNNotificationSetting::Enabled => Some(true),
            UNNotificationSetting::Disabled => Some(false),
            _ => None,
        }
    }

    /// True when the running process has a real bundle identity.
    ///
    /// `UNUserNotificationCenter::currentNotificationCenter()` raises an
    /// Objective-C exception in a process with no bundle identifier, which is
    /// exactly the case under `cargo test` and a plain `cargo run`. Checking
    /// first keeps unit tests and dev binaries from aborting.
    pub fn has_bundle_identity() -> bool {
        NSBundle::mainBundle().bundleIdentifier().is_some()
    }

    /// Status used when the authoritative query cannot run.
    pub fn unavailable_status() -> NotificationPermissionStatusDto {
        NotificationPermissionStatusDto {
            platform: NotificationPlatform::Macos,
            supported: true,
            authorization: NotificationAuthorization::Unknown,
            alerts_enabled: None,
            sounds_enabled: None,
            requested: false,
            // Not authoritative: we could not actually ask the OS.
            authoritative: false,
            can_open_settings: true,
        }
    }

    fn read_settings(settings: &UNNotificationSettings) -> NotificationPermissionStatusDto {
        let authorization = map_authorization_status(settings.authorizationStatus());
        NotificationPermissionStatusDto {
            platform: NotificationPlatform::Macos,
            supported: true,
            authorization,
            alerts_enabled: map_notification_setting(settings.alertSetting()),
            sounds_enabled: map_notification_setting(settings.soundSetting()),
            requested: authorization != NotificationAuthorization::NotDetermined,
            authoritative: true,
            can_open_settings: true,
        }
    }

    /// Query `UNNotificationSettings`, returning `None` when unavailable.
    fn query_settings() -> Option<NotificationPermissionStatusDto> {
        if !has_bundle_identity() {
            return None;
        }

        let (tx, rx) = mpsc::sync_channel::<NotificationPermissionStatusDto>(1);
        // The completion handler may run on an arbitrary queue; the channel
        // marshals a plain Rust DTO back to the caller.
        let handler = RcBlock::new(move |settings: NonNull<UNNotificationSettings>| {
            let status = read_settings(unsafe { settings.as_ref() });
            let _ = tx.try_send(status);
        });

        let dispatched = objc2::exception::catch(std::panic::AssertUnwindSafe(|| {
            let center = UNUserNotificationCenter::currentNotificationCenter();
            center.getNotificationSettingsWithCompletionHandler(&handler);
        }));

        if dispatched.is_err() {
            tracing::warn!("UNUserNotificationCenter settings query raised an exception");
            return None;
        }

        match rx.recv_timeout(CALLBACK_TIMEOUT) {
            Ok(status) => Some(status),
            Err(_) => {
                tracing::warn!("UNUserNotificationCenter settings query timed out");
                None
            }
        }
    }

    #[derive(Debug, Default, Clone, Copy)]
    pub struct MacosPermissionProvider;

    impl NotificationPermissionProvider for MacosPermissionProvider {
        fn status(&self) -> NotificationPermissionStatusDto {
            query_settings().unwrap_or_else(unavailable_status)
        }

        fn request(&self) -> NotificationPermissionRequestDto {
            if !has_bundle_identity() {
                return NotificationPermissionRequestDto {
                    granted: false,
                    status: unavailable_status(),
                    error: Some(
                        "notification authorization requires a bundled application".into(),
                    ),
                };
            }

            let (tx, rx) = mpsc::sync_channel::<Result<bool, String>>(1);
            let handler = RcBlock::new(
                move |granted: objc2::runtime::Bool, error: *mut NSError| {
                    let outcome = if error.is_null() {
                        Ok(granted.as_bool())
                    } else {
                        Err(unsafe { (*error).localizedDescription() }.to_string())
                    };
                    let _ = tx.try_send(outcome);
                },
            );

            // Alert + sound only; badge and critical alerts are not needed.
            let options = UNAuthorizationOptions::Alert | UNAuthorizationOptions::Sound;
            let dispatched = objc2::exception::catch(std::panic::AssertUnwindSafe(|| {
                let center = UNUserNotificationCenter::currentNotificationCenter();
                center.requestAuthorizationWithOptions_completionHandler(options, &handler);
            }));

            if dispatched.is_err() {
                return NotificationPermissionRequestDto {
                    granted: false,
                    status: unavailable_status(),
                    error: Some("notification authorization request failed".into()),
                };
            }

            let (granted, error) = match rx.recv_timeout(CALLBACK_TIMEOUT) {
                Ok(Ok(granted)) => (granted, None),
                Ok(Err(message)) => (false, Some(message)),
                Err(_) => (false, Some("authorization request timed out".to_string())),
            };

            // Re-query settings: the callback boolean alone describes neither
            // alert/sound state nor a later change in System Settings.
            let status = query_settings().unwrap_or_else(unavailable_status);

            NotificationPermissionRequestDto {
                granted,
                status,
                error,
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn desktop_fallback_never_claims_authorized() {
        let status = DesktopFallbackPermissionProvider.status();

        // Tauri's desktop permission_state() would report "granted" here; the
        // fallback must not repeat that unverifiable claim.
        assert_eq!(status.authorization, NotificationAuthorization::Unknown);
        assert!(!status.authoritative);
        assert!(status.supported);
        assert!(!status.is_blocked());
        assert!(!status.needs_permission_request());
    }

    #[test]
    fn desktop_fallback_request_reports_status_without_prompting() {
        let result = DesktopFallbackPermissionProvider.request();

        assert!(!result.granted);
        assert_eq!(
            result.status.authorization,
            NotificationAuthorization::Unknown
        );
        assert!(result.error.is_none());
    }

    #[test]
    fn platform_provider_status_is_never_authoritatively_authorized_in_tests() {
        // `cargo test` has no bundle identity, so macOS cannot return an
        // authoritative grant. This guards against a provider that fakes one.
        let status = platform_permission_provider().status();

        assert!(
            !(status.authoritative
                && status.authorization == NotificationAuthorization::Authorized),
            "unbundled test process must not report authoritative authorization"
        );
    }

    #[cfg(target_os = "macos")]
    mod macos_mapping {
        use super::super::macos::{
            has_bundle_identity, map_authorization_status, map_notification_setting,
            unavailable_status,
        };
        use crate::notification::model::NotificationAuthorization;
        use objc2_user_notifications::{UNAuthorizationStatus, UNNotificationSetting};

        #[test]
        fn authorization_status_maps_every_known_value() {
            assert_eq!(
                map_authorization_status(UNAuthorizationStatus::NotDetermined),
                NotificationAuthorization::NotDetermined
            );
            assert_eq!(
                map_authorization_status(UNAuthorizationStatus::Denied),
                NotificationAuthorization::Denied
            );
            assert_eq!(
                map_authorization_status(UNAuthorizationStatus::Authorized),
                NotificationAuthorization::Authorized
            );
